ref = date(2025, 8, 12)
severities = ['ERROR', 'WARNING', 'INFO']
periods = ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']
counts = {p: {s: 0 for s in severities} for p in periods}
sev_re = re.compile(r'\b(ERROR|WARNING|INFO)\b')

for path in sorted(logs_dir.glob('*.log')):
    # filenames follow YYYY-MM-DD_<source>.log
    try:
        log_date = datetime.strptime(path.name[:10], '%Y-%m-%d').date()
    except ValueError:
        continue

    in_period = {
        'today': log_date == ref,
        'last_7_days': ref - timedelta(days=6) <= log_date <= ref,
        'last_30_days': ref - timedelta(days=29) <= log_date <= ref,
        'month_to_date': date(ref.year, ref.month, 1) <= log_date <= ref,
        'total': True,
    }

    with path.open('r', encoding='utf-8', errors='replace') as f:
        for line in f:
            for m in sev_re.finditer(line):
                sev = m.group(1)
                for period, include in in_period.items():
                    if include:
                        counts[period][sev] += 1

with outfile.open('w', newline='', encoding='utf-8') as f:
    writer = csv.writer(f)
    writer.writerow(['period', 'severity', 'count'])
    for period in periods:
        for sev in severities:
            writer.writerow([period, sev, counts[period][sev]])
