/*
 * High-performance portfolio calculations using C extension
 *
 * Implements:
 *   risk   = sqrt(x^T S x)
 *   return = x^T r
 *
 * The risk calculation intentionally follows the same two-step order as the
 * Python baseline (temp = S*x, then x^T*temp) to keep floating point results
 * as close as possible while moving the expensive loops into C.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array = NULL;
    PyArrayObject *cov_array = NULL;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &cov_array)) {
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights must be a 1D NumPy array");
        return NULL;
    }
    if (PyArray_NDIM(cov_array) != 2) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must be a 2D NumPy array");
        return NULL;
    }
    if (PyArray_TYPE(weights_array) != NPY_DOUBLE || PyArray_TYPE(cov_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "arrays must have dtype float64");
        return NULL;
    }
    if (!PyArray_IS_C_CONTIGUOUS(weights_array) || !PyArray_IS_C_CONTIGUOUS(cov_array)) {
        PyErr_SetString(PyExc_ValueError, "arrays must be C-contiguous");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(cov_array, 0) != n || PyArray_DIM(cov_array, 1) != n) {
        PyErr_SetString(PyExc_ValueError, "cov_matrix must have shape (len(weights), len(weights))");
        return NULL;
    }

    const double *weights = (const double *)PyArray_DATA(weights_array);
    const double *cov = (const double *)PyArray_DATA(cov_array);

    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (temp == NULL) {
        PyErr_NoMemory();
        return NULL;
    }

    double risk_squared = 0.0;

    Py_BEGIN_ALLOW_THREADS

    /* Step 1: temp = S * x, matching Python baseline loop order. */
    for (npy_intp i = 0; i < n; ++i) {
        const double *row = cov + i * n;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            row_sum += row[j] * weights[j];
        }
        temp[i] = row_sum;
    }

    /* Step 2: risk_squared = x^T * temp. */
    for (npy_intp i = 0; i < n; ++i) {
        risk_squared += weights[i] * temp[i];
    }

    Py_END_ALLOW_THREADS

    free(temp);

    if (risk_squared < 0.0 && risk_squared > -1e-15) {
        risk_squared = 0.0;
    }

    return PyFloat_FromDouble(sqrt(risk_squared));
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_array = NULL;
    PyArrayObject *returns_array = NULL;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_array,
                                       &PyArray_Type, &returns_array)) {
        return NULL;
    }

    if (PyArray_NDIM(weights_array) != 1 || PyArray_NDIM(returns_array) != 1) {
        PyErr_SetString(PyExc_ValueError, "weights and expected_returns must be 1D NumPy arrays");
        return NULL;
    }
    if (PyArray_TYPE(weights_array) != NPY_DOUBLE || PyArray_TYPE(returns_array) != NPY_DOUBLE) {
        PyErr_SetString(PyExc_TypeError, "arrays must have dtype float64");
        return NULL;
    }
    if (!PyArray_IS_C_CONTIGUOUS(weights_array) || !PyArray_IS_C_CONTIGUOUS(returns_array)) {
        PyErr_SetString(PyExc_ValueError, "arrays must be C-contiguous");
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights_array, 0);
    if (PyArray_DIM(returns_array, 0) != n) {
        PyErr_SetString(PyExc_ValueError, "weights and expected_returns must have the same length");
        return NULL;
    }

    const double *weights = (const double *)PyArray_DATA(weights_array);
    const double *returns = (const double *)PyArray_DATA(returns_array);

    double total_return = 0.0;

    Py_BEGIN_ALLOW_THREADS
    for (npy_intp i = 0; i < n; ++i) {
        total_return += weights[i] * returns[i];
    }
    Py_END_ALLOW_THREADS

    return PyFloat_FromDouble(total_return);
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
